package expo.modules.rncompatibility

import com.facebook.react.internal.featureflags.ReactNativeFeatureFlags

/**
 * A compatibility helper of
 * `com.facebook.react.config.ReactFeatureFlags` and
 * `com.facebook.react.internal.featureflags.ReactNativeFeatureFlags`
 */
object ReactNativeFeatureFlags {
  // enableBridgelessArchitecture() doesn't exist in RN 0.74.3
  val enableBridgelessArchitecture = try {
    ReactNativeFeatureFlags::class.java.getMethod("enableBridgelessArchitecture").invoke(null) as? Boolean ?: false
  } catch (e: Exception) {
    false
  }
}
